{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required payload fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty array")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be an array of strings")

    required = set(required_symbols)
    by_id = {}
    source_order = {}

    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node missing required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or node_id == "":
            raise ValueError("node id must be a non-empty string")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be a boolean")
        if not isinstance(utility, (int, float)) or isinstance(utility, bool):
            raise ValueError("utility must be numeric")

        if "grammar_valid" in node and not isinstance(node["grammar_valid"], bool):
            raise ValueError("grammar_valid must be boolean when present")
        if "interestingness_preserved" in node and not isinstance(node["interestingness_preserved"], bool):
            raise ValueError("interestingness_preserved must be boolean when present")

        by_id[node_id] = node
        source_order[node_id] = index

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must contain exactly one root")
    root_id = roots[0]["id"]
    if roots[0]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node["id"]: [] for node in nodes}
    for node in nodes:
        node_id = node["id"]
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("parent reference does not exist")
        if by_id[parent]["depth"] + 1 != node["depth"]:
            raise ValueError("node depth is inconsistent with parent")
        children[parent].append(node_id)

    represented = set(node["symbol"] for node in nodes)
    if not required.issubset(represented):
        raise ValueError("required symbol is not represented")

    retained = set(by_id.keys())
    removed_order = []

    candidates = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    for node in candidates:
        node_id = node["id"]
        if node_id == root_id:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if node.get("grammar_valid", True) is not True:
            continue
        if node.get("interestingness_preserved", True) is not True:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        remaining_symbols = set(by_id[kept_id]["symbol"] for kept_id in retained if kept_id != node_id)
        if not required.issubset(remaining_symbols):
            continue

        retained.remove(node_id)
        removed_order.append(node_id)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": sorted(retained),
    }
"}
